import{_ as l,l as o,o as e,c as n,v as t,p as s,x as r,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"撞库与速率限制","description":"","frontmatter":{"title":"撞库与速率限制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/credential-stuffing.md","filePath":"cs/credential-stuffing.md","lastUpdated":1789023840000}'),p={name:"cs/credential-stuffing.md"};function f(u,a,A,_,m,E){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="撞库与速率限制" tabindex="-1">撞库与速率限制 <a class="header-anchor" href="#撞库与速率限制" aria-label="Permalink to &quot;撞库与速率限制&quot;">​</a></h1><div class="epigraph"><p>别处泄漏的口令会被拿到你这再试。速率限制、多因素、泄漏口令检测降低自动化成功率；复杂密码规则挡不住已泄漏的那条。</p><footer>—— 据 OWASP Credential Stuffing；NIST SP 800-63B；对照[密码破解](/cs/password-cracking)</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/business-logic-flaws">业务逻辑</a>是工作流。缺口是<strong>认证入口被自动化</strong>。离线破解是哈希；本课是在线。不给撞库操作指导。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户复用口令。攻击者持泄漏对。缺口：速率限制要按账户与地址分层、锁定策略防 DoS、MFA、已知泄漏口令检查。</p><h3 id="验证码不是根" tabindex="-1">验证码不是根 <a class="header-anchor" href="#验证码不是根" aria-label="Permalink to &quot;验证码不是根&quot;">​</a></h3><p>可被农场绕过。作辅助信号。</p><p><span class="marginnote">OWASP。禁止撞库教程。WAF 下一课是另一层过滤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层限流、谨慎的设备信号、无口令或 WebAuthn。下一课 WAF。</p>',12)),(e(),s(h,null,{default:r(()=>[c(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEAK%5B%22%E5%A4%96%E9%83%A8%E6%B3%84%E6%BC%8F%E5%AF%B9%22%5D%20--%3E%20TRY%5B%22%E5%9C%A8%E4%BD%A0%E8%BF%99%E7%99%BB%E5%BD%95%22%5D%0A%20%20TRY%20--%3E%20RL%5B%22%E9%80%9F%E7%8E%87%E9%99%90%E5%88%B6%22%5D%0A%20%20TRY%20--%3E%20MFA%5B%22%E7%AC%AC%E4%BA%8C%E5%9B%A0%E7%B4%A0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>在线模型受接口约束，故限流有效；对已泄漏高价值账户仍要 MFA。WAF 下一课挡一部分自动化与注入噪声。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写工具用法。WAF 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>逻辑洞之后，认证口仍会被泄漏口令打。</li><li>限流、MFA、禁已知泄漏。</li><li>在线不等于离线哈希破解。</li><li>下一课 WAF。</li><li>出处：OWASP Credential Stuffing；NIST SP 800-63B。</li></ul>',8))])}const T=l(p,[["render",f]]);export{S as __pageData,T as default};
